// Bluetooth lab B6 Keyboard & media.  uv run pio run -d labs/ble-lab-b6 -e ble-lab-b6 -t upload
// The board becomes a Bluetooth keyboard with media keys. Pair it like any keyboard (phone or Mac
// Bluetooth settings: "Bench B6"), then the button is a remote: play/pause the music on your phone,
// skip tracks, change the volume (that music can be playing on your JBL: the phone talks to the
// speaker, the board talks to the phone), click through slides, or type text from the serial monitor.
//
// Wiring: the screen from lesson 03. Optional: the push button on GPIO 5 (does what BOOT does), and
// two jumper wires on GPIO 1 and GPIO 2 as touch keys for volume down / up (`touch on`).
//
// Views: media · slides · typer · keys · link · log
//   media and slides are modes: click / double-click / hold act there; hold 2 s = next view.
//   elsewhere: click = next view, double-click = the footer's action.
// Serial: help lists the commands. Shared code: kit/lib/ble-kit. HID: hid_keyboard.h, keymap.h.
#include <Preferences.h>

#include "b6_views.h"
#include "ble_lab.h"
#include "hid_keyboard.h"
#include "keymap.h"
#include "server_link.h"
#include "touch_pads.h"

namespace {

ble::ServerLink links;
b6::Keyboard kb;
b6::Screen screen;
Preferences prefs;
constexpr uint8_t kTouchPins[2] = {1, 2};  // volume down, volume up
TouchPads<2> touch(kTouchPins);
uint32_t touchRepeatAt = 0;

// A long press in a mode view waits: released before 2 s = the mode's long action,
// still held at 2 s = next view.
uint32_t holdSince = 0;
uint8_t holdPin = 0;

bool needReady(BleLab &lab) {
  if (b6::Keyboard::ready()) return true;
  lab.warn("not paired yet: open Bluetooth settings on your phone or Mac and pick \"%s\"", lab.spec().deviceName);
  return false;
}

void sendMedia(BleLab &lab, uint16_t usage) {
  if (!needReady(lab)) return;
  kb.mediaKey(usage);
  screen.lastMedia = usage;
  screen.lastMediaAt = millis();
  if (usage == b6::media::kPlayPause) screen.playing = !screen.playing;
  if (usage == b6::media::kMute) screen.muted = !screen.muted;
  if (usage == b6::media::kVolumeUp) screen.volumeSteps++, screen.muted = false;
  if (usage == b6::media::kVolumeDown) screen.volumeSteps--;
  BLE_NOTE(Tx, "media key: %s (usage %03X)", b6::mediaName(usage), usage);
}

void sendKey(BleLab &lab, keymap::Stroke s, const char *what, char ch = 0) {
  if (!needReady(lab)) return;
  if (!kb.tap(s, ch)) return lab.warn("typing queue full, wait a moment");
  BLE_NOTE(Tx, "key %s (mod %02X key %02X)", what, s.mod, s.key);
}

void slide(BleLab &lab, int dir) {
  if (!needReady(lab)) return;
  sendKey(lab, {0, dir > 0 ? keymap::key::kRight : keymap::key::kLeft}, dir > 0 ? "right arrow" : "left arrow");
  screen.slide = std::max(1, screen.slide + dir);
  screen.slideDir = dir;
  screen.slideAt = millis();
  screen.black = false;
}

// Queue text, character by character, with the chosen layout. Returns the keys queued.
int typeText(BleLab &lab, const char *text) {
  if (!needReady(lab)) return 0;
  String skipped;
  int n = 0;
  for (const char *p = text; *p; p++) {
    const keymap::Stroke s = keymap::fromChar(*p, screen.layout);
    if (s.key == 0) {
      if (skipped.indexOf(*p) < 0) skipped += *p;
      continue;
    }
    if (!kb.tap(s, *p)) {
      lab.warn("typing queue full after %d characters", n);
      break;
    }
    n++;
  }
  if (skipped.length()) lab.warn("%s can't type \"%s\": skipped", keymap::layoutName(screen.layout), skipped.c_str());
  // The tail of the text, for the typer view.
  const size_t len = strlen(text);
  strlcpy(screen.typed, len > 46 ? text + len - 46 : text, sizeof(screen.typed));
  screen.total = n;
  BLE_NOTE(Tx, "typing %d keys (%s)", n, screen.layout == keymap::Layout::US ? "US" : "DE");
  return n;
}

// ---- Views ------------------------------------------------------------------------------------

void drawMedia(BleLab &, FrameBuffer &fb, float t) { b6v::media(fb, screen, t); }
void drawSlides(BleLab &, FrameBuffer &fb, float t) { b6v::slides(fb, screen, t); }
void drawTyper(BleLab &, FrameBuffer &fb, float t) { b6v::typer(fb, screen, kb.hostLeds(), t); }
void drawKeys(BleLab &, FrameBuffer &fb, float t) { b6v::keys(fb, kb, screen.layout, t); }
void drawLink(BleLab &lab, FrameBuffer &fb, float t) { bv::link(fb, lab.state(), t, "keyboard"); }
void drawLog(BleLab &, FrameBuffer &fb, float) { bv::log(fb); }

constexpr int kMediaView = 0, kSlidesView = 1;
const BleView kViews[] = {
    {"media", drawMedia, "media next"},
    {"slides", drawSlides, "key left"},
    {"typer", drawTyper, "snippet"},
    {"keys", drawKeys, "key shift"},
    {"link", drawLink, nullptr},
    {"log", drawLog, nullptr},
};

// ---- Commands ---------------------------------------------------------------------------------

void cmdType(BleLab &lab, const String &arg, const String &) {
  if (arg.isEmpty()) return lab.warn("type <text>, e.g. type hello bench");
  typeText(lab, arg.c_str());
  lab.showView("typer");
}

void cmdKey(BleLab &lab, const String &, const String &lower) {
  keymap::Stroke s;
  if (!keymap::fromName(lower.c_str(), s))
    return lab.warn("key <name>: enter tab esc space backspace delete up down left right home end pageup pagedown f1-f12, a letter; "
                    "combos with cmd ctrl alt shift, e.g. key cmd+space");
  sendKey(lab, s, lower.c_str());
}

void cmdLayout(BleLab &lab, const String &, const String &lower) {
  if (lower != "us" && lower != "de") return lab.warn("layout us | layout de   (match the layout set on the computer)");
  screen.layout = lower == "us" ? keymap::Layout::US : keymap::Layout::DE;
  prefs.putUChar("layout", uint8_t(screen.layout));
  BLE_NOTE(Info, "layout %s (saved)", keymap::layoutName(screen.layout));
}

void cmdSnippet(BleLab &lab, const String &arg, const String &) {
  if (arg.isEmpty()) {
    if (!screen.snippet[0]) return lab.warn("no snippet yet: snippet <text> saves one");
    typeText(lab, screen.snippet);
    return;
  }
  strlcpy(screen.snippet, arg.c_str(), sizeof(screen.snippet));
  prefs.putString("snippet", screen.snippet);
  BLE_NOTE(Info, "snippet saved: double-click on the typer view types it");
}

void cmdMedia(BleLab &lab, const String &, const String &lower) {
  if (lower == "play" || lower == "pause") return sendMedia(lab, b6::media::kPlayPause);
  if (lower == "next") return sendMedia(lab, b6::media::kNext);
  if (lower == "prev" || lower == "previous") return sendMedia(lab, b6::media::kPrevious);
  if (lower == "up") return sendMedia(lab, b6::media::kVolumeUp);
  if (lower == "down") return sendMedia(lab, b6::media::kVolumeDown);
  if (lower == "mute") return sendMedia(lab, b6::media::kMute);
  lab.warn("media play | next | prev | up | down | mute");
}

void cmdTouch(BleLab &lab, const String &, const String &lower) {
  if (lower != "on" && lower != "off") return lab.warn("touch on | touch off   (jumpers on GPIO 1 = volume down, GPIO 2 = up)");
  touch.enable(lower == "on");
  screen.touchOn = touch.on();
  if (touch.on()) BLE_NOTE(Good, "touch on: baselines %lu / %lu, hands off while measuring", static_cast<unsigned long>(touch.baseline(0)),
                           static_cast<unsigned long>(touch.baseline(1)));
  else BLE_NOTE(Info, "touch off");
}

void cmdForget(BleLab &, const String &, const String &) {
  const ble::LinkState s = ble::link().get();
  NimBLEDevice::deleteAllBonds();
  if (s.radio == ble::Radio::Connected) NimBLEDevice::getServer()->disconnect(s.peer.handle);
  BLE_NOTE(Warn, "bonds deleted here. Also forget \"Bench B6\" on the phone/Mac");
}

const BleCommand kCommands[] = {
    {"type", "<text>", "type text into the paired phone/Mac", cmdType},
    {"key", "<name|combo>", "one key or combo: enter, f5, cmd+space, ctrl+alt+delete", cmdKey},
    {"layout", "us|de", "the computer's keyboard layout (saved)", cmdLayout},
    {"snippet", "[text]", "save a text (alone: type it; typer view 2x too)", cmdSnippet},
    {"media", "<key>", "play next prev up down mute", cmdMedia},
    {"touch", "on|off", "touch wires on GPIO 1/2 = volume down/up", cmdTouch},
    {"forget", "", "delete the bond (then forget the board on the phone too)", cmdForget},
};

// ---- Hooks ------------------------------------------------------------------------------------

void setup(BleLab &lab) {
  prefs.begin("b6", false);
  screen.layout = keymap::Layout(prefs.getUChar("layout", 0) == 1 ? 1 : 0);
  strlcpy(screen.snippet, prefs.getString("snippet", "").c_str(), sizeof(screen.snippet));
  // Bonding yes, man-in-the-middle protection no (no screen on a keyboard... well, we have one,
  // but hosts expect a keyboard to pair like one), LE Secure Connections yes.
  NimBLEDevice::setSecurityAuth(true, false, true);
  NimBLEDevice::setSecurityIOCap(BLE_HS_IO_NO_INPUT_OUTPUT);
  NimBLEServer *server = NimBLEDevice::createServer();
  server->setCallbacks(&links, false);
  kb.begin(server);
  server->start();
  kb.advertise(lab.spec().deviceName);
  BLE_NOTE(Info, "layout %s. Pair: Bluetooth settings > Bench B6", keymap::layoutName(screen.layout));
}

void tick(BleLab &lab) {
  kb.pump();
  screen.queued = kb.pending();
  screen.ready = b6::Keyboard::ready();
  // A long press waiting for its outcome (mode views).
  if (holdSince) {
    if (digitalRead(holdPin) == HIGH) {
      holdSince = 0;
      if (lab.view() == kMediaView) sendMedia(lab, b6::media::kMute);
      else if (lab.view() == kSlidesView && needReady(lab)) {
        sendKey(lab, keymap::fromChar('b', keymap::Layout::US), "b (black screen)", 'b');
        screen.black = !screen.black;
      }
    } else if (millis() - holdSince >= 1400) {  // + the 600 ms before LongPress fired = 2 s
      holdSince = 0;
      lab.setView(lab.view() + 1);
    }
  }
  // Touch volume: a touch = one step, keep touching = repeat every 300 ms.
  uint32_t released = 0;
  const uint32_t pressed = touch.poll(released);
  for (int i = 0; i < 2; i++) {
    screen.touchRise[i] = touch.rise(i);
    if ((pressed >> i) & 1) {
      sendMedia(lab, i == 0 ? b6::media::kVolumeDown : b6::media::kVolumeUp);
      touchRepeatAt = millis() + 500;
    } else if (touch.down(i) && millis() > touchRepeatAt) {
      sendMedia(lab, i == 0 ? b6::media::kVolumeDown : b6::media::kVolumeUp);
      touchRepeatAt = millis() + 300;
    }
  }
}

// In the two mode views the button is the remote. Double-click falls through to the view action.
bool gesture(BleLab &lab, Gesture g, bool external) {
  const int v = lab.view();
  if (v != kMediaView && v != kSlidesView) return false;
  switch (g) {
    case Gesture::Click:
      if (v == kMediaView) sendMedia(lab, b6::media::kPlayPause);
      else slide(lab, +1);
      return true;
    case Gesture::LongPress:
      holdSince = millis();
      holdPin = external ? PIN_BUTTON : PIN_BOOT_BTN;
      return true;
    case Gesture::DoubleClick:
      if (v == kSlidesView) {
        slide(lab, -1);
        return true;
      }
      return false;  // media: the view action, "media next"
  }
  return false;
}

const BleLabSpec kSpec{
    "ble-lab-b6", "B6", "Keyboard & media", "Bench B6", kViews, sizeof(kViews) / sizeof(kViews[0]), 0,
    kCommands, sizeof(kCommands) / sizeof(kCommands[0]), setup, tick, gesture, nullptr,
};

BleLab lab(kSpec);

}  // namespace

void setup() { lab.begin(); }

void loop() { lab.loop(); }

// B6's screens (320 x 170). The first two are modes: there the button IS the remote.
//   media   transport and volume icons; the last key pressed ripples, and a dot runs the sound
//           path: board -(BLE HID)-> phone/Mac -(Classic audio)-> speaker
//   slides  a slide deck: right arrow, left arrow, b for a black screen (Keynote, PowerPoint, Slides)
//   typer   what `type` is sending, the layout, the snippet, the computer's Caps/Num Lock lights
//   keys    the last reports byte by byte: modifier bits, the key numbers, what they type
#pragma once

#include <Fonts/FreeSansBold18pt7b.h>
#include <Fonts/FreeSansBold24pt7b.h>

#include "ble_views.h"
#include "hid_keyboard.h"
#include "keymap.h"

namespace b6 {

struct Screen {
  keymap::Layout layout = keymap::Layout::US;
  uint16_t lastMedia = 0;
  uint32_t lastMediaAt = 0;
  bool playing = false;  // our guess: every play/pause flips it
  bool muted = false;
  int volumeSteps = 0;   // up minus down since power-on (the computer knows the real volume)
  int slide = 1;
  int slideDir = 0;
  uint32_t slideAt = 0;
  bool black = false;
  char typed[48] = "";   // the tail of what `type` queued
  int queued = 0, total = 0;
  char snippet[64] = "";
  bool touchOn = false;
  int touchRise[2] = {};
  bool ready = false;    // connected + encrypted
};

}  // namespace b6

namespace b6v {

using namespace bv;

// ---- small icons, centred on (x, y) ----

inline void play(FrameBuffer &fb, int x, int y, int s, uint16_t c) { fb.fillTriangle(x - s / 2, y - s, x - s / 2, y + s, x + s, y, c); }
inline void pause(FrameBuffer &fb, int x, int y, int s, uint16_t c) {
  fb.fillRect(x - s + 1, y - s, s * 2 / 3, s * 2, c);
  fb.fillRect(x + s / 3, y - s, s * 2 / 3, s * 2, c);
}
inline void skip(FrameBuffer &fb, int x, int y, int s, bool forward, uint16_t c) {
  const int d = forward ? 1 : -1;
  fb.fillTriangle(x - d * s, y - s, x - d * s, y + s, x, y, c);
  fb.fillTriangle(x, y - s, x, y + s, x + d * s, y, c);
  fb.fillRect(forward ? x + s : x - s - 2, y - s, 3, s * 2 + 1, c);
}
inline void speaker(FrameBuffer &fb, int x, int y, int waves, bool muted, uint16_t c) {
  fb.fillRect(x - 10, y - 4, 6, 8, c);
  fb.fillTriangle(x - 5, y - 4, x + 2, y - 10, x + 2, y + 10, c);
  fb.fillTriangle(x - 5, y + 4, x + 2, y - 10, x + 2, y + 10, c);
  if (muted) {
    fb.drawLine(x + 6, y - 5, x + 14, y + 5, pal::coral);
    fb.drawLine(x + 6, y + 5, x + 14, y - 5, pal::coral);
    return;
  }
  for (int i = 0; i < waves; i++) fb.drawCircleHelper(x + 2, y, 5 + i * 4, 0x2 | 0x4, c);
}

// The legend at the bottom of a mode view: what each gesture does here.
inline void legend(FrameBuffer &fb, const char *text) {
  fb.drawFastHLine(0, 144, kW, pal::dim);
  small(fb, 6, 148, pal::muted, text);
}

// board -> phone -> speaker: the first hop is ours (Bluetooth LE), the second is the phone's own
// Classic Bluetooth audio link. A dot runs it after every media key.
inline void soundPath(FrameBuffer &fb, int y, uint32_t sinceKey, bool ready) {
  const int xs[3] = {20, 150, 280};
  const char *const labels[3] = {"this board", "phone / Mac", "your speaker"};
  for (int i = 0; i < 3; i++) {
    fb.drawRoundRect(xs[i] - 16, y - 7, 32, 14, 3, i == 0 ? kBlue : pal::muted);
    small(fb, xs[i] - int(strlen(labels[i])) * 3, y + 10, pal::muted, labels[i]);
  }
  fb.drawFastHLine(xs[0] + 17, y, xs[1] - xs[0] - 34, ready ? kBlue : pal::dim);
  fb.drawFastHLine(xs[1] + 17, y, xs[2] - xs[1] - 34, pal::amber);
  small(fb, 58, y - 10, kBlue, "BLE HID");
  small(fb, 180, y - 10, pal::amber, "Classic audio");
  if (sinceKey < 900) {
    const float k = sinceKey / 900.0f;
    const int x = k < 0.5f ? xs[0] + 17 + int(k * 2 * (xs[1] - xs[0] - 34)) : xs[1] + 17 + int((k - 0.5f) * 2 * (xs[2] - xs[1] - 34));
    fb.fillCircle(x, y, 3, k < 0.5f ? kBlue : pal::amber);
  }
}

inline void media(FrameBuffer &fb, const b6::Screen &s, float t) {
  const uint32_t since = millis() - s.lastMediaAt;
  struct Btn {
    int x;
    uint16_t usage;
  };
  const Btn btns[] = {{36, b6::media::kPrevious}, {96, b6::media::kPlayPause}, {156, b6::media::kNext}, {222, b6::media::kVolumeDown}, {282, b6::media::kVolumeUp}};
  const int y = 66;
  for (const Btn &b : btns) {
    const bool hot = s.lastMedia == b.usage && since < 500;
    const uint16_t c = hot ? pal::ink : s.ready ? pal::muted : pal::dim;
    if (hot) fb.drawCircle(b.x, y, 20 + int(since / 25), mix(kBlue, pal::night, uint8_t(since * 255 / 500)));
    fb.drawCircle(b.x, y, b.usage == b6::media::kPlayPause ? 22 : 17, hot ? kBlue : pal::dim);
    switch (b.usage) {
      case b6::media::kPrevious: skip(fb, b.x, y, 7, false, c); break;
      case b6::media::kNext: skip(fb, b.x, y, 7, true, c); break;
      case b6::media::kPlayPause: s.playing ? pause(fb, b.x, y, 9, c) : play(fb, b.x, y, 10, c); break;
      case b6::media::kVolumeDown: speaker(fb, b.x + 2, y, 1, false, c), fb.drawFastHLine(b.x - 6, y + 13, 10, c); break;
      case b6::media::kVolumeUp: speaker(fb, b.x, y, 2, false, c), fb.drawFastHLine(b.x - 6, y + 13, 10, c), fb.drawFastVLine(b.x - 1, y + 9, 9, c); break;
    }
  }
  char v[48];
  if (s.lastMedia && since < 4000) snprintf(v, sizeof(v), "sent: %s%s", b6::mediaName(s.lastMedia), s.muted && s.lastMedia == b6::media::kMute ? " (toggle)" : "");
  else if (!s.ready) snprintf(v, sizeof(v), "pair me: Bluetooth settings > Bench B6");
  else snprintf(v, sizeof(v), "volume %+d steps since power-on%s", s.volumeSteps, s.touchOn ? ", touch 1/2" : "");
  small(fb, 8, 96, s.ready ? pal::ink : pal::amber, v);
  soundPath(fb, 120, since, s.ready);
  legend(fb, "click play/pause, 2x next, hold mute, hold 2 s: view");
  (void)t;
}

inline void slides(FrameBuffer &fb, const b6::Screen &s, float t) {
  // The deck: the current slide slides in from the side we moved to.
  const uint32_t since = millis() - s.slideAt;
  const float k = since < 300 ? 1 - since / 300.0f : 0;
  const int off = int(k * k * 120) * s.slideDir;
  const int x = 90 + off, y = 40;
  if (s.black) {
    fb.fillRoundRect(90, y, 140, 82, 4, 0);
    fb.drawRoundRect(90, y, 140, 82, 4, pal::dim);
    small(fb, 112, y + 38, pal::muted, "black screen (b)");
  } else {
    fb.drawRoundRect(x - 6, y + 4, 140, 82, 4, pal::dim);  // the next slide, peeking
    fb.fillRoundRect(x, y, 140, 82, 4, kPanel);
    fb.drawRoundRect(x, y, 140, 82, 4, pal::ink);
    fb.fillRect(x + 12, y + 12, 70, 6, pal::muted);
    fb.fillRect(x + 12, y + 26, 100, 3, pal::dim);
    fb.fillRect(x + 12, y + 34, 90, 3, pal::dim);
    char n[8];
    snprintf(n, sizeof(n), "%d", s.slide);
    fb.setFont(&FreeSansBold18pt7b);
    fb.setTextColor(pal::ink);
    fb.setCursor(x + 98, y + 72);
    fb.print(n);
  }
  // Arrows: which key went out.
  const bool hot = since < 500;
  fb.fillTriangle(60, 81, 72, 71, 72, 91, hot && s.slideDir < 0 ? kBlue : pal::dim);
  fb.fillTriangle(260, 81, 248, 71, 248, 91, hot && s.slideDir > 0 ? kBlue : pal::dim);
  small(fb, 8, 128, s.ready ? pal::muted : pal::amber, s.ready ? "keys: right arrow, left arrow, b" : "pair me first, then open your slides");
  legend(fb, "click next, 2x back, hold black, hold 2 s: view");
  (void)t;
}

inline void typer(FrameBuffer &fb, const b6::Screen &s, uint8_t hostLeds, float t) {
  char v[64];
  stat(fb, 8, 34, "layout (layout us|de)", keymap::layoutName(s.layout), kBlue);
  // The computer's lock lights, sent back to us in the output report.
  small(fb, 196, 34, pal::muted, "computer's lights");
  const char *const names[] = {"Num", "Caps", "Scroll"};
  for (int i = 0; i < 3; i++) {
    const bool on = (hostLeds >> i) & 1;
    fb.fillCircle(202 + i * 40, 52, 4, on ? pal::teal : pal::dim);
    small(fb, 209 + i * 40, 49, on ? pal::ink : pal::muted, names[i]);
  }
  // The text box, with a blinking cursor after what was typed.
  fb.drawRoundRect(6, 66, 308, 26, 4, pal::dim);
  small(fb, 12, 75, s.typed[0] ? pal::ink : pal::muted, s.typed[0] ? s.typed : "serial: type hello bench");
  if (int(t * 2) & 1) fb.fillRect(14 + int(strlen(s.typed)) * 6, 73, 2, 10, kBlue);
  if (s.total) {
    const int done = s.total - s.queued / 2;
    fb.fillRect(6, 96, 308 * done / s.total, 3, s.queued ? pal::amber : pal::teal);
    snprintf(v, sizeof(v), s.queued ? "typing: %d of %d keys" : "typed %d keys", done, s.total);
    small(fb, 6, 104, s.queued ? pal::amber : pal::muted, v);
  }
  snprintf(v, sizeof(v), "snippet: %.40s", s.snippet[0] ? s.snippet : "(none: snippet <text>)");
  small(fb, 6, 122, pal::muted, v);
}

inline void keys(FrameBuffer &fb, const b6::Keyboard &kb, keymap::Layout layout, float t) {
  const uint32_t n = kb.sentCount();
  if (n == 0) {
    small(fb, 8, 46, pal::muted, "No reports yet. Pair, then press the button");
    small(fb, 8, 58, pal::muted, "or type: key enter, type hi");
    return;
  }
  const b6::Sent s = kb.last(0);
  const uint32_t age = millis() - s.at;
  // The newest report as boxes; a packet runs to the computer on the right.
  small(fb, 6, 34, pal::muted, s.consumer ? "report 2 (media): usage, little-endian" : "report 1 (keyboard): mod, 0, key x6");
  const int bytes = s.consumer ? 2 : 8;
  for (int i = 0; i < bytes; i++) {
    const int x = 6 + i * 30;
    const bool live = s.report[i] != 0;
    fb.fillRoundRect(x, 46, 27, 18, 3, live ? (s.press ? kBlue : kPanel) : kPanel);
    char h[4];
    snprintf(h, sizeof(h), "%02X", s.report[i]);
    small(fb, x + 8, 52, live ? pal::ink : pal::muted, h);
  }
  fb.drawRoundRect(276, 40, 38, 28, 3, pal::muted);
  small(fb, 280, 50, pal::muted, "host");
  if (age < 400) fb.fillCircle(6 + bytes * 30 + int((276 - 6 - bytes * 30) * age / 400), 55, 3, s.press ? kBlue : kViolet);
  if (!s.consumer) {
    // Modifier byte, bit by bit: right GUI ... left Control.
    const char *const mods[] = {"LCtl", "LShf", "LAlt", "LGui", "RCtl", "RShf", "RAlt", "RGui"};
    for (int b = 0; b < 8; b++) {
      const bool on = (s.report[0] >> b) & 1;
      small(fb, 6 + b * 38, 70, on ? pal::amber : pal::dim, mods[b]);
    }
  }
  // The last few, newest first: press/release, bytes, what the host makes of it.
  for (uint32_t i = 0; i < 5 && i < n; i++) {
    const b6::Sent r = kb.last(i);
    char v[64];
    if (r.consumer)
      snprintf(v, sizeof(v), "%s media %02X %02X  %s", r.press ? "down" : "up  ", r.report[0], r.report[1],
               r.press ? b6::mediaName(uint16_t(r.report[0] | (r.report[1] << 8))) : "(released)");
    else if (r.press)
      snprintf(v, sizeof(v), "down mod %02X key %02X  %s%c%s", r.report[0], r.report[2], r.shown ? "types '" : "", r.shown ? r.shown : ' ',
               r.shown ? "'" : "");
    else
      snprintf(v, sizeof(v), "up   all zero: every key released");
    small(fb, 6, 84 + int(i) * 11, i == 0 ? pal::ink : pal::muted, v);
  }
  char v[48];
  snprintf(v, sizeof(v), "layout on this side: %s", keymap::layoutName(layout));
  small(fb, 6, 142, kBlue, v);
  (void)t;
}

}  // namespace b6v

// The board as a Bluetooth keyboard with media keys: "HID over GATT" (HOGP).
//
// A Bluetooth LE keyboard is just a GATT server with a standard service, HID (1812). Its most
// important characteristic is the Report Map (2A4B): a small program in the HID descriptor
// language that tells the computer what our reports mean. After reading it once, the computer
// subscribes to the Input Report characteristics (2A4D) and we send a notification for every
// change: key down, key up. No driver needed: phones, Macs and PCs all ship one.
//
// Two reports, told apart by their Report ID:
//   1 keyboard  8 bytes: modifiers (one bit each), a reserved 0, up to six keys held at once
//               plus an output report the other way: the computer's Caps/Num Lock lights
//   2 consumer  2 bytes: one "consumer control" usage, 16-bit: play/pause, volume, next track
//
// HID hosts insist on an encrypted link (the input reports are READ_ENC), so the first connection
// pairs and bonds (Just Works + Secure Connections: a keyboard without a screen can't show a code).
#pragma once

#include <Arduino.h>
#include <NimBLEDevice.h>
#include <NimBLEHIDDevice.h>

#include "ble_link.h"
#include "keymap.h"
#include "server_link.h"

namespace b6 {

// Consumer page usages (HID Usage Tables, page 0x0C).
namespace media {
constexpr uint16_t kPlayPause = 0x00CD, kNext = 0x00B5, kPrevious = 0x00B6;
constexpr uint16_t kVolumeUp = 0x00E9, kVolumeDown = 0x00EA, kMute = 0x00E2;
}  // namespace media

inline const char *mediaName(uint16_t u) {
  switch (u) {
    case media::kPlayPause: return "play/pause";
    case media::kNext: return "next track";
    case media::kPrevious: return "previous track";
    case media::kVolumeUp: return "volume up";
    case media::kVolumeDown: return "volume down";
    case media::kMute: return "mute";
    default: return "media key";
  }
}

// The Report Map, byte by byte. Each item is a tag byte (what + how many data bytes) and its data.
static const uint8_t kReportMap[] = {
    // ---- Report 1: a keyboard ----
    0x05, 0x01,        // Usage Page (Generic Desktop)
    0x09, 0x06,        // Usage (Keyboard)
    0xA1, 0x01,        // Collection (Application)
    0x85, 0x01,        //   Report ID 1
    0x05, 0x07,        //   Usage Page (Keyboard/Keypad)
    0x19, 0xE0,        //   Usage Minimum (Left Control)
    0x29, 0xE7,        //   Usage Maximum (Right GUI): the 8 modifier keys
    0x15, 0x00,        //   Logical Minimum (0)
    0x25, 0x01,        //   Logical Maximum (1)
    0x75, 0x01,        //   Report Size (1 bit)
    0x95, 0x08,        //   Report Count (8)
    0x81, 0x02,        //   Input (Data, Variable, Absolute): byte 0 = one bit per modifier
    0x95, 0x01,        //   Report Count (1)
    0x75, 0x08,        //   Report Size (8)
    0x81, 0x01,        //   Input (Constant): byte 1 = reserved, always 0
    0x95, 0x05,        //   Report Count (5)
    0x75, 0x01,        //   Report Size (1)
    0x05, 0x08,        //   Usage Page (LEDs)
    0x19, 0x01,        //   Usage Minimum (Num Lock)
    0x29, 0x05,        //   Usage Maximum (Kana)
    0x91, 0x02,        //   Output (Data, Variable, Absolute): the computer tells us its lock lights
    0x95, 0x01,        //   Report Count (1)
    0x75, 0x03,        //   Report Size (3)
    0x91, 0x01,        //   Output (Constant): pad the lights to a whole byte
    0x95, 0x06,        //   Report Count (6)
    0x75, 0x08,        //   Report Size (8)
    0x15, 0x00,        //   Logical Minimum (0)
    0x25, 0x65,        //   Logical Maximum (101)
    0x05, 0x07,        //   Usage Page (Keyboard/Keypad)
    0x19, 0x00,        //   Usage Minimum (0)
    0x29, 0x65,        //   Usage Maximum (101)
    0x81, 0x00,        //   Input (Data, Array): bytes 2-7 = the keys held, by number
    0xC0,              // End Collection
    // ---- Report 2: media keys ----
    0x05, 0x0C,        // Usage Page (Consumer)
    0x09, 0x01,        // Usage (Consumer Control)
    0xA1, 0x01,        // Collection (Application)
    0x85, 0x02,        //   Report ID 2
    0x15, 0x00,        //   Logical Minimum (0)
    0x26, 0xFF, 0x03,  //   Logical Maximum (1023)
    0x19, 0x00,        //   Usage Minimum (0)
    0x2A, 0xFF, 0x03,  //   Usage Maximum (1023)
    0x75, 0x10,        //   Report Size (16 bits)
    0x95, 0x01,        //   Report Count (1)
    0x81, 0x00,        //   Input (Data, Array): one usage, 0 = released
    0xC0,              // End Collection
};

// What the keys view draws: the last reports we sent.
struct Sent {
  uint8_t report[8] = {};
  bool consumer = false;   // true = report 2 (the first 2 bytes count)
  bool press = false;      // false = the release that follows
  uint32_t at = 0;
  char shown = 0;          // the character this press types with the current layout, 0 = none
};

class Keyboard : public NimBLECharacteristicCallbacks {
 public:
  void begin(NimBLEServer *server) {
    hid_ = new NimBLEHIDDevice(server);
    hid_->setManufacturer("Hardware Diary bench");
    // PnP ID: source 2 = USB-IF vendor id. 0x303A is Espressif's USB vendor id; product is made up.
    hid_->setPnp(0x02, 0x303A, 0xB006, 0x0100);
    hid_->setHidInfo(0x00, 0x01);  // country 0 (not localised), flags: can wake the host
    hid_->setReportMap(const_cast<uint8_t *>(kReportMap), sizeof(kReportMap));
    keys_ = hid_->getInputReport(1);
    media_ = hid_->getInputReport(2);
    leds_ = hid_->getOutputReport(1);
    leds_->setCallbacks(this);
    hid_->setBatteryLevel(100);  // on USB power
  }

  // Advertise as a keyboard: the HID service and the keyboard appearance (a keyboard icon on the
  // phone's Bluetooth list), the name in the same packet so every host shows it.
  void advertise(const char *name) {
    NimBLEAdvertising *adv = NimBLEDevice::getAdvertising();
    NimBLEAdvertisementData data;
    data.setFlags(BLE_HS_ADV_F_DISC_GEN | BLE_HS_ADV_F_BREDR_UNSUP);
    data.setAppearance(HID_KEYBOARD);
    data.addServiceUUID(NimBLEUUID(uint16_t(0x1812)));
    data.setName(name);
    adv->setAdvertisementData(data);
    if (adv->start()) {
      ble::link().edit([](ble::LinkState &s) { s.radio = ble::Radio::Advertising, s.advertising = true; });
      BLE_NOTE(Info, "advertising as keyboard \"%s\"", name);
    }
  }

  // Ready = connected AND encrypted: before that, the host can't read our reports.
  static bool ready() {
    const ble::LinkState s = ble::link().get();
    return s.radio == ble::Radio::Connected && s.peer.encrypted;
  }

  // ---- The typing queue: loop() sends a few events per frame, 8 ms apart ----------------------

  enum class Ev : uint8_t { Down, Up, Media, MediaUp };
  struct Event {
    Ev ev;
    keymap::Stroke stroke;
    uint16_t usage;
    char ch;
  };

  bool tap(keymap::Stroke s, char ch = 0) { return push({Ev::Down, s, 0, ch}) && push({Ev::Up, {}, 0, 0}); }
  bool mediaKey(uint16_t usage) { return push({Ev::Media, {}, usage, 0}) && push({Ev::MediaUp, {}, 0, 0}); }
  int pending() const { return int(tail_ - head_); }
  void clear() { head_ = tail_ = 0; }

  // From loop(): send up to 6 events, 8 ms apart (the host needs to see each key go down and up).
  void pump() {
    for (int n = 0; n < 6 && head_ != tail_; n++) {
      if (n) delay(8);
      send(queue_[head_++ % kQueue]);
    }
    if (head_ == tail_) head_ = tail_ = 0;
  }

  Sent last(int i) const { return sent_[(sentHead_ - 1 - i + kSent * 4) % kSent]; }
  uint32_t sentCount() const { return sentHead_; }
  uint8_t hostLeds() const { return hostLeds_; }

  // The computer writes its lock lights (bit 0 Num, 1 Caps, 2 Scroll) into the output report.
  void onWrite(NimBLECharacteristic *c, NimBLEConnInfo &) override {
    const NimBLEAttValue v = c->getValue();
    if (v.size() < 1) return;
    hostLeds_ = v.data()[0];
    ble::countRx(v.size());
    BLE_NOTE(Rx, "host lights: Caps %s, Num %s", hostLeds_ & 2 ? "on" : "off", hostLeds_ & 1 ? "on" : "off");
  }

 private:
  static constexpr int kQueue = 256, kSent = 8;

  bool push(const Event &e) {
    if (tail_ - head_ >= uint32_t(kQueue)) return false;
    queue_[tail_++ % kQueue] = e;
    return true;
  }

  void send(const Event &e) {
    Sent s;
    s.at = millis();
    if (e.ev == Ev::Down || e.ev == Ev::Up) {
      s.press = e.ev == Ev::Down;
      if (s.press) s.report[0] = e.stroke.mod, s.report[2] = e.stroke.key, s.shown = e.ch;
      keys_->setValue(s.report, 8);
      keys_->notify();
      ble::countTx(8);
    } else {
      s.consumer = true;
      s.press = e.ev == Ev::Media;
      if (s.press) s.report[0] = uint8_t(e.usage & 0xFF), s.report[1] = uint8_t(e.usage >> 8);
      media_->setValue(s.report, 2);
      media_->notify();
      ble::countTx(2);
    }
    sent_[sentHead_++ % kSent] = s;
  }

  NimBLEHIDDevice *hid_ = nullptr;
  NimBLECharacteristic *keys_ = nullptr, *media_ = nullptr, *leds_ = nullptr;
  Event queue_[kQueue];
  uint32_t head_ = 0, tail_ = 0;
  Sent sent_[kSent];
  uint32_t sentHead_ = 0;
  volatile uint8_t hostLeds_ = 0;
};

}  // namespace b6

// From a character to the key a keyboard would press. No Arduino here, so
// labs/ble-lab-b6/test/host/ble_keymap_test.cpp checks it on the Mac.
//
// A USB or Bluetooth keyboard never sends letters. It sends key numbers ("usages" from the HID
// Keyboard page): 0x04 is the key where a US keyboard prints A, 0x1C the key where it prints Y.
// The computer turns that number into a character with ITS layout setting. So on a Mac set to
// German, key 0x1C types z: the German keyboard has z where the US one has y.
//
// That's why the board needs to know your layout to type "yes": `layout de` picks the German
// table. Characters a layout can only reach with AltGr/Option (@ [ ] { } \ | ~ on German) differ
// between Windows and macOS, so the German table skips them rather than guess.
#pragma once

#include <ctype.h>
#include <stdint.h>
#include <string.h>

namespace keymap {

// Modifier bits in the first byte of a keyboard report.
constexpr uint8_t kCtrl = 0x01, kShift = 0x02, kAlt = 0x04, kGui = 0x08;  // left side
constexpr uint8_t kRightAlt = 0x40;                                          // AltGr on Windows

enum class Layout : uint8_t { US, DE };

inline const char *layoutName(Layout l) { return l == Layout::US ? "US (QWERTY)" : "German (QWERTZ)"; }

// One key press: the modifiers held and the key. key 0 = this layout can't type it.
struct Stroke {
  uint8_t mod = 0;
  uint8_t key = 0;
};

namespace key {
constexpr uint8_t kA = 0x04, kZ = 0x1D, k1 = 0x1E, k0 = 0x27;
constexpr uint8_t kEnter = 0x28, kEsc = 0x29, kBackspace = 0x2A, kTab = 0x2B, kSpace = 0x2C;
constexpr uint8_t kMinus = 0x2D, kEqual = 0x2E, kLeftBracket = 0x2F, kRightBracket = 0x30, kBackslash = 0x31;
constexpr uint8_t kSemicolon = 0x33, kQuote = 0x34, kGrave = 0x35, kComma = 0x36, kDot = 0x37, kSlash = 0x38;
constexpr uint8_t kCapsLock = 0x39, kF1 = 0x3A, kF12 = 0x45;
constexpr uint8_t kHome = 0x4A, kPageUp = 0x4B, kDelete = 0x4C, kEnd = 0x4D, kPageDown = 0x4E;
constexpr uint8_t kRight = 0x4F, kLeft = 0x50, kDown = 0x51, kUp = 0x52;
constexpr uint8_t kNonUsBackslash = 0x64;  // the extra key next to left Shift on ISO keyboards: < > on German
}  // namespace key

// ---- US: what the HID usage tables are named after ---------------------------------------------

inline Stroke usChar(char c) {
  using namespace key;
  if (c >= 'a' && c <= 'z') return {0, uint8_t(kA + (c - 'a'))};
  if (c >= 'A' && c <= 'Z') return {kShift, uint8_t(kA + (c - 'A'))};
  if (c >= '1' && c <= '9') return {0, uint8_t(k1 + (c - '1'))};
  switch (c) {
    case '0': return {0, k0};
    case '\n': return {0, kEnter};
    case '\t': return {0, kTab};
    case ' ': return {0, kSpace};
    // The shifted digits, as printed on a US keyboard: !@#$%^&*()
    case '!': return {kShift, uint8_t(k1 + 0)};
    case '@': return {kShift, uint8_t(k1 + 1)};
    case '#': return {kShift, uint8_t(k1 + 2)};
    case '$': return {kShift, uint8_t(k1 + 3)};
    case '%': return {kShift, uint8_t(k1 + 4)};
    case '^': return {kShift, uint8_t(k1 + 5)};
    case '&': return {kShift, uint8_t(k1 + 6)};
    case '*': return {kShift, uint8_t(k1 + 7)};
    case '(': return {kShift, uint8_t(k1 + 8)};
    case ')': return {kShift, k0};
    case '-': return {0, kMinus};
    case '_': return {kShift, kMinus};
    case '=': return {0, kEqual};
    case '+': return {kShift, kEqual};
    case '[': return {0, kLeftBracket};
    case '{': return {kShift, kLeftBracket};
    case ']': return {0, kRightBracket};
    case '}': return {kShift, kRightBracket};
    case '\\': return {0, kBackslash};
    case '|': return {kShift, kBackslash};
    case ';': return {0, kSemicolon};
    case ':': return {kShift, kSemicolon};
    case '\'': return {0, kQuote};
    case '"': return {kShift, kQuote};
    case '`': return {0, kGrave};
    case '~': return {kShift, kGrave};
    case ',': return {0, kComma};
    case '<': return {kShift, kComma};
    case '.': return {0, kDot};
    case '>': return {kShift, kDot};
    case '/': return {0, kSlash};
    case '?': return {kShift, kSlash};
    default: return {};
  }
}

// ---- German: the same physical keys, other characters ------------------------------------------

inline Stroke deChar(char c) {
  using namespace key;
  // y and z swap places; every other letter stays.
  if (c == 'y') return {0, kZ};
  if (c == 'z') return {0, uint8_t(kA + ('y' - 'a'))};
  if (c == 'Y') return {kShift, kZ};
  if (c == 'Z') return {kShift, uint8_t(kA + ('y' - 'a'))};
  if (isalpha(static_cast<unsigned char>(c)) || (c >= '0' && c <= '9') || c == '\n' || c == '\t' || c == ' ') return usChar(c);
  switch (c) {
    // Shift + digit: !"§$%&/()=
    case '!': return {kShift, uint8_t(k1 + 0)};
    case '"': return {kShift, uint8_t(k1 + 1)};
    case '$': return {kShift, uint8_t(k1 + 3)};
    case '%': return {kShift, uint8_t(k1 + 4)};
    case '&': return {kShift, uint8_t(k1 + 5)};
    case '/': return {kShift, uint8_t(k1 + 6)};
    case '(': return {kShift, uint8_t(k1 + 7)};
    case ')': return {kShift, uint8_t(k1 + 8)};
    case '=': return {kShift, k0};
    case '?': return {kShift, kMinus};          // the ß key
    case '+': return {0, kRightBracket};        // where US has ]
    case '*': return {kShift, kRightBracket};
    case '#': return {0, kBackslash};           // the key left of Enter
    case '\'': return {kShift, kBackslash};
    case ',': return {0, kComma};
    case ';': return {kShift, kComma};
    case '.': return {0, kDot};
    case ':': return {kShift, kDot};
    case '-': return {0, kSlash};               // where US has /
    case '_': return {kShift, kSlash};
    case '<': return {0, kNonUsBackslash};
    case '>': return {kShift, kNonUsBackslash};
    // @ [ ] { } \ | ~ need AltGr (Windows) or Option (Mac) on different keys: skipped.
    // ^ and ` are dead keys (they wait for the next letter): skipped too.
    default: return {};
  }
}

inline Stroke fromChar(char c, Layout l) { return l == Layout::US ? usChar(c) : deChar(c); }

// ---- Named keys and combos: "enter", "f5", "cmd+space", "ctrl+alt+delete" ------------------------

inline bool sameText(const char *a, size_t n, const char *b) { return strlen(b) == n && strncmp(a, b, n) == 0; }

inline bool namedKey(const char *s, size_t n, uint8_t &out) {
  using namespace key;
  struct Name {
    const char *name;
    uint8_t key;
  };
  static const Name names[] = {{"enter", kEnter}, {"return", kEnter}, {"esc", kEsc}, {"escape", kEsc}, {"backspace", kBackspace},
                               {"tab", kTab}, {"space", kSpace}, {"capslock", kCapsLock}, {"home", kHome}, {"pageup", kPageUp},
                               {"delete", kDelete}, {"del", kDelete}, {"end", kEnd}, {"pagedown", kPageDown}, {"right", kRight},
                               {"left", kLeft}, {"down", kDown}, {"up", kUp}};
  for (const Name &nm : names)
    if (sameText(s, n, nm.name)) return out = nm.key, true;
  // f1 ... f12
  if (n >= 2 && n <= 3 && s[0] == 'f' && isdigit(static_cast<unsigned char>(s[1]))) {
    const int f = n == 2 ? s[1] - '0' : (s[1] - '0') * 10 + (s[2] - '0');
    if (n == 3 && !isdigit(static_cast<unsigned char>(s[2]))) return false;
    if (f >= 1 && f <= 12) return out = uint8_t(kF1 + f - 1), true;
  }
  // One letter or digit: the key in its US position (with cmd/ctrl, shortcuts follow the key).
  if (n == 1 && (isalnum(static_cast<unsigned char>(s[0])))) {
    const Stroke st = usChar(char(tolower(static_cast<unsigned char>(s[0]))));
    return out = st.key, st.key != 0;
  }
  return false;
}

inline bool modifierName(const char *s, size_t n, uint8_t &mod) {
  if (sameText(s, n, "cmd") || sameText(s, n, "gui") || sameText(s, n, "win") || sameText(s, n, "super")) return mod |= kGui, true;
  if (sameText(s, n, "ctrl") || sameText(s, n, "control")) return mod |= kCtrl, true;
  if (sameText(s, n, "alt") || sameText(s, n, "option") || sameText(s, n, "opt")) return mod |= kAlt, true;
  if (sameText(s, n, "shift")) return mod |= kShift, true;
  return false;
}

// "cmd+shift+4" -> {Gui|Shift, key 4}. Lower-case input. False if any part is unknown.
inline bool fromName(const char *text, Stroke &out) {
  Stroke st;
  const char *p = text;
  while (*p) {
    const char *plus = strchr(p, '+');
    const size_t n = plus ? size_t(plus - p) : strlen(p);
    if (n == 0) return false;
    if (plus) {
      if (plus[1] == 0 || !modifierName(p, n, st.mod)) return false;  // "cmd+" with nothing after
      p = plus + 1;
    } else {
      // The last part may be a modifier on its own ("shift"): press just that.
      if (!namedKey(p, n, st.key) && !modifierName(p, n, st.mod)) return false;
      p += n;
    }
  }
  if (st.key == 0 && st.mod == 0) return false;
  out = st;
  return true;
}

}  // namespace keymap

// The shell every Bluetooth LE lab (B1-B8) shares: the screen with its status bar, the push button
// and BOOT, the on-board LED, serial commands, and printing the activity log.
//
// A lab is a BleLabSpec: its views (each one a draw function, plus what a double-click does there),
// its serial commands, and three hooks: setup() once NimBLE is running, tick() on every loop, and
// gesture() to give the button a lab-specific meaning. Each src/ble-lab-bN/main.cpp is that list.
//
// Button or BOOT, by default: click = next view · double-click = this view's action · long press =
// the lab's long action. While a numeric comparison waits: click = yes, long press = no.
// On-board LED, unless the lab claims it: breathing blue = advertising · cyan pulse = scanning ·
// steady blue = connected · violet = encrypted · amber blink = a passkey waits · white blink = data.
#pragma once

#include <Arduino.h>
#include <NimBLEDevice.h>

#include "ble_link.h"
#include "ble_views.h"
#include "button.h"
#include "display.h"
#include "pins.h"

class BleLab;

enum class Gesture : uint8_t { Click, DoubleClick, LongPress };

struct BleCommand {
  const char *name;  // the first word you type
  const char *args;  // for help, e.g. "<dBm>"
  const char *what;  // one line for help
  void (*run)(BleLab &lab, const String &arg, const String &lower);
};

struct BleView {
  const char *name;  // "radar"
  void (*draw)(BleLab &lab, FrameBuffer &fb, float t);
  const char *action;  // the command line a double-click runs on this view, or nullptr
};

struct BleLabSpec {
  const char *env;         // "ble-lab-b1"
  const char *id;          // "B1"
  const char *title;       // "Listen"
  const char *deviceName;  // what phones see: "Bench B3"
  const BleView *views;
  int viewCount;
  int startView;
  const BleCommand *commands;
  int commandCount;
  void (*setup)(BleLab &lab) = nullptr;  // after NimBLE is initialised
  void (*tick)(BleLab &lab) = nullptr;   // every loop, before drawing
  // First say on every gesture. Return true when handled, false for the default.
  bool (*gesture)(BleLab &lab, Gesture g, bool external) = nullptr;
  const char *longAction = nullptr;  // the command line a long press runs by default
};

class BleLab {
 public:
  explicit BleLab(const BleLabSpec &spec) : spec_(spec), view_(spec.startView) {}

  void begin() {
    Serial.begin(115200);
    delay(1500);
    if (!display_.begin()) {
      log_e("No memory for the frame buffer. Stopping.");
      return;
    }
    rgbLedWrite(PIN_RGB, 0, 0, 0);
    external_.begin();
    boot_.begin();
    if (!NimBLEDevice::init(spec_.deviceName)) {
      log_e("NimBLE did not start. Stopping.");
      return;
    }
    Serial.printf("\n%s: NimBLE %s up, address %s, TX power %d dBm\n", spec_.env, NimBLEDevice::getVersion(),
                  NimBLEDevice::getAddress().toString().c_str(), NimBLEDevice::getPower());
    if (spec_.setup) spec_.setup(*this);
    printHelp();
  }

  void loop() {
    FrameBuffer &fb = display_.fb();
    if (fb.pixels() == nullptr) {
      delay(1000);
      return;
    }
    pollSerial();
    handleButton(external_, true);
    handleButton(boot_, false);
    measureRssi();
    if (spec_.tick) spec_.tick(*this);
    link_ = ble::link().get();
    printActivity();
    showLed();

    const float t = millis() / 1000.0f;
    const BleView &v = spec_.views[view_];
    fb.fillScreen(pal::night);
    v.draw(*this, fb, t);
    if (passkeyShowing()) bv::passkey(fb, link_, t);
    bv::header(fb, spec_.id, v.name, view_, spec_.viewCount, link_, t);
    char hint[40];
    if (passkeyShowing() && link_.passkeyCompare) snprintf(hint, sizeof(hint), "click = yes, long = no");
    else if (v.action) snprintf(hint, sizeof(hint), "2x: %s", v.action);
    else snprintf(hint, sizeof(hint), "click: next view");
    bv::footer(fb, hint);
    display_.push();
  }

  // ---- For views and commands ------------------------------------------------------------------

  const ble::LinkState &state() const { return link_; }
  const BleLabSpec &spec() const { return spec_; }
  int view() const { return view_; }

  void setView(int v) {
    view_ = (v % spec_.viewCount + spec_.viewCount) % spec_.viewCount;
    log_i("view %d: %s", view_ + 1, spec_.views[view_].name);
  }
  void showView(const char *name) {
    for (int i = 0; i < spec_.viewCount; i++)
      if (strcmp(spec_.views[i].name, name) == 0) return setView(i);
  }

  // The lab drives the on-board LED itself (B3's LED characteristic); false hands it back.
  void claimLed(bool claimed) {
    ledClaimed_ = claimed;
    ledShown_ = 0xFFFFFFFF;
  }

  // log_w is a macro that can't be returned from a void function; this can.
  [[gnu::format(printf, 2, 3)]] void warn(const char *fmt, ...) {
    char text[120];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(text, sizeof(text), fmt, ap);
    va_end(ap);
    log_w("%s", text);
  }

  // Parse a number argument; false when it is missing, not a number or out of range.
  static bool number(const String &arg, long lo, long hi, long &out) {
    if (arg.isEmpty()) return false;
    for (size_t i = 0; i < arg.length(); i++)
      if (!isDigit(arg[i]) && !(i == 0 && arg[i] == '-')) return false;
    out = arg.toInt();
    return out >= lo && out <= hi;
  }

  void runLine(const String &raw) {
    String line = raw;
    line.trim();
    if (line.isEmpty()) return;
    const int sp = line.indexOf(' ');
    String cmd = sp < 0 ? line : line.substring(0, sp);
    String arg = sp < 0 ? String() : line.substring(sp + 1);
    cmd.toLowerCase();
    arg.trim();
    String lower = arg;
    lower.toLowerCase();
    if (cmd == "help" || cmd == "?") return printHelp();
    if (cmd == "view") {
      long n = 0;
      if (!number(arg, 1, spec_.viewCount, n)) return warn("view <1-%d>", spec_.viewCount);
      return setView(n - 1);
    }
    if (cmd == "status") return printStatus();
    if (cmd == "power") return power(arg);
    for (int i = 0; i < spec_.commandCount; i++)
      if (cmd == spec_.commands[i].name) return spec_.commands[i].run(*this, arg, lower);
    log_w("unknown command '%s' in %s (type help)", line.c_str(), spec_.env);
  }

 private:
  bool passkeyShowing() const { return link_.passkey != 0 && millis() - link_.passkeySince < 30000; }

  void printHelp() {
    Serial.printf("\nBluetooth lab %s %s  (%s)  ·  phones see \"%s\"\n", spec_.id, spec_.title, spec_.env, spec_.deviceName);
    for (int i = 0; i < spec_.commandCount; i++) {
      const BleCommand &c = spec_.commands[i];
      char usage[40];
      snprintf(usage, sizeof(usage), "%s %s", c.name, c.args);
      Serial.printf("  %-28s %s\n", usage, c.what);
    }
    Serial.printf("  %-28s %s\n", "status", "the radio, the link and its security, in detail");
    Serial.printf("  %-28s %s\n", "power <dBm>", "transmit power: -24 to 20 (default 9)");
    Serial.printf("  %-28s %s\n", "view <n>", "show screen view n");
    Serial.print("Views:");
    for (int i = 0; i < spec_.viewCount; i++)
      Serial.printf(" %d %s%s", i + 1, spec_.views[i].name, i + 1 < spec_.viewCount ? " ·" : "\n");
    Serial.println("Button (GPIO 5, optional) or BOOT: click = next view, double-click = the view's action");
  }

  void printStatus() {
    const ble::LinkState s = ble::link().get();
    Serial.printf("radio %s · this board %s · TX power %d dBm\n", ble::radioName(s.radio), NimBLEDevice::getAddress().toString().c_str(),
                  NimBLEDevice::getPower());
    if (s.radio != ble::Radio::Connected) {
      if (s.lastDisconnect >= 0) Serial.printf("last link ended: 0x%02X %s\n", s.lastDisconnect & 0xFF, ble::disconnectReason(s.lastDisconnect));
      return;
    }
    const ble::Peer &p = s.peer;
    Serial.printf("peer %s%s%s (%s) · we are the %s\n", p.addr, p.idAddr[0] ? " id " : "", p.idAddr, p.name[0] ? p.name : "no name",
                  p.central ? "peripheral" : "central");
    Serial.printf("interval %.2f ms · latency %u · timeout %u ms · MTU %u · PHY %u/%u · RSSI %d dBm\n", p.interval * 1.25f, p.latency,
                  p.timeout * 10, p.mtu, p.txPhy, p.rxPhy, p.rssi);
    Serial.printf("security: %s, %s, %s, key %u bytes\n", p.encrypted ? "encrypted" : "not encrypted",
                  p.authenticated ? "authenticated (MITM)" : "not authenticated", p.bonded ? "bonded" : "not bonded", p.keySize);
    Serial.printf("traffic: rx %lu ops / %lu B · tx %lu ops / %lu B\n", static_cast<unsigned long>(s.rxOps), static_cast<unsigned long>(s.rxBytes),
                  static_cast<unsigned long>(s.txOps), static_cast<unsigned long>(s.txBytes));
  }

  void power(const String &arg) {
    long dbm = 0;
    if (!number(arg, -24, 20, dbm)) return warn("power <dBm>, -24 to 20. Now %d dBm", NimBLEDevice::getPower());
    if (!NimBLEDevice::setPower(int8_t(dbm))) return warn("the radio refused %ld dBm", dbm);
    BLE_NOTE(Info, "TX power %d dBm", NimBLEDevice::getPower());
  }

  void pollSerial() {
    static String buffer;
    while (Serial.available()) {
      const char c = Serial.read();
      if (c == '\n' || c == '\r') {
        if (!buffer.isEmpty()) runLine(buffer);
        buffer = "";
      } else if (c == 0x08 || c == 0x7F) {
        if (!buffer.isEmpty()) buffer.remove(buffer.length() - 1);
      } else if (uint8_t(c) < 0x20) {
        // Other control characters (arrow keys send escape sequences): ignore.
      } else if (buffer.length() < 120) {
        buffer += c;
      }
    }
  }

  void handleButton(Button &b, bool external) {
    Gesture g;
    switch (b.poll()) {
      case Button::Event::Click: g = Gesture::Click; break;
      case Button::Event::DoubleClick: g = Gesture::DoubleClick; break;
      case Button::Event::LongPress: g = Gesture::LongPress; break;
      default: return;
    }
    if (spec_.gesture && spec_.gesture(*this, g, external)) return;
    switch (g) {
      case Gesture::Click: setView(view_ + 1); break;
      case Gesture::DoubleClick:
        if (spec_.views[view_].action) {
          Serial.printf("> %s   (double-click)\n", spec_.views[view_].action);
          runLine(spec_.views[view_].action);
        }
        break;
      case Gesture::LongPress:
        if (spec_.longAction) {
          Serial.printf("> %s   (long press)\n", spec_.longAction);
          runLine(spec_.longAction);
        }
        break;
    }
  }

  // RSSI of a live link: the controller measures it on every connection event; we ask once a second.
  void measureRssi() {
    const ble::LinkState &s = link_;
    if (s.radio != ble::Radio::Connected || millis() - rssiAt_ < 1000) return;
    rssiAt_ = millis();
    int8_t rssi = 0;
    if (ble_gap_conn_rssi(s.peer.handle, &rssi) == 0) ble::link().edit([&](ble::LinkState &st) { st.peer.rssi = rssi; });
  }

  // New activity lines go to serial from here, in order, never from the NimBLE task.
  void printActivity() {
    ble::Activity &a = ble::activity();
    const uint32_t head = a.head();
    if (printed_ + ble::Activity::kSize < head) {
      Serial.printf("  ... %lu lines skipped\n", static_cast<unsigned long>(head - ble::Activity::kSize - printed_));
      printed_ = head - ble::Activity::kSize;
    }
    ble::ActEntry e;
    for (; printed_ < head; printed_++)
      if (a.get(printed_, e)) Serial.printf("  %s %s\n", bv::actMark(e.kind), e.text);
  }

  void showLed() {
    if (ledClaimed_) return;
    const uint32_t now = millis();
    const uint32_t traffic = link_.rxOps + link_.txOps;
    if (traffic != traffic_) traffic_ = traffic, flashUntil_ = now + 60;
    // Brightness in 12 steps, so the LED (a whole WS2812 frame per write) is only rewritten on a change.
    const float wave = 0.5f + 0.5f * sinf(now / 1000.0f * 3.1416f);
    const uint8_t breathe = uint8_t(int(wave * 11) * 8 + 6);
    uint8_t r = 0, g = 0, b = 0;
    if (passkeyShowing()) r = (now / 250) & 1 ? 120 : 0, g = r / 2;
    else if (now < flashUntil_) r = 120, g = 120, b = 120;
    else switch (link_.radio) {
      case ble::Radio::Off: break;
      case ble::Radio::Scanning: g = breathe / 2, b = breathe / 2; break;
      case ble::Radio::Advertising: b = breathe; break;
      case ble::Radio::Connecting: r = 60, g = 40; break;
      case ble::Radio::Connected:
        if (link_.peer.encrypted) r = 50, b = 90;
        else b = 90;
        break;
    }
    const uint32_t colour = (uint32_t(r) << 16) | (uint32_t(g) << 8) | b;
    if (colour == ledShown_) return;
    ledShown_ = colour;
    rgbLedWrite(PIN_RGB, r, g, b);
  }

  const BleLabSpec &spec_;
  Display display_;
  Button external_{PIN_BUTTON, "button"};
  Button boot_{PIN_BOOT_BTN, "BOOT"};
  ble::LinkState link_;
  int view_;
  bool ledClaimed_ = false;
  uint32_t ledShown_ = 0xFFFFFFFF, flashUntil_ = 0, traffic_ = 0, rssiAt_ = 0, printed_ = 0;
};

// The peripheral side of a link (B3-B7): NimBLE's server callbacks, turned into ble::link() state
// and activity lines. Labs make one, hand it to the server, and override what they need.
//
// Pairing hooks are here too, because every lab after B3 meets them: a passkey to show, a number
// to compare. The passkey goes into the link state; the shell draws it over any view, and the
// button (click = yes, long press = no) or serial `yes`/`no` answers through confirm().
#pragma once

#include <Arduino.h>
#include <NimBLEDevice.h>
#include <esp_random.h>

#include "ble_link.h"

namespace ble {

inline void fillPeer(Peer &p, const NimBLEConnInfo &c) {
  strlcpy(p.addr, c.getAddress().toString().c_str(), sizeof(p.addr));
  const NimBLEAddress id = c.getIdAddress();
  if (!(id == c.getAddress())) strlcpy(p.idAddr, id.toString().c_str(), sizeof(p.idAddr));
  else p.idAddr[0] = 0;
  p.addrType = c.getAddress().getType();
  p.handle = c.getConnHandle();
  p.mtu = c.getMTU();
  p.interval = c.getConnInterval();
  p.latency = c.getConnLatency();
  p.timeout = c.getConnTimeout();
  p.encrypted = c.isEncrypted();
  p.authenticated = c.isAuthenticated();
  p.bonded = c.isBonded();
  p.keySize = c.getSecKeySize();
  p.central = c.isSlave();  // we are the slave (peripheral), so the peer is the central
}

class ServerLink : public NimBLEServerCallbacks {
 public:
  // Advertising starts again by itself after a disconnect (NimBLE's advertiseOnDisconnect).
  void onConnect(NimBLEServer *, NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) {
      s.peer = Peer{};
      fillPeer(s.peer, c);
      s.radio = Radio::Connected;
      s.advertising = false;
      s.connections++;
      s.connectedAt = millis();
      s.rxOps = s.txOps = s.rxBytes = s.txBytes = 0;
    });
    BLE_NOTE(Good, "connected: %s", c.getAddress().toString().c_str());
    BLE_NOTE(Info, "interval %.2f ms, latency %u, timeout %u ms", c.getConnInterval() * 1.25f, c.getConnLatency(), c.getConnTimeout() * 10);
  }

  void onDisconnect(NimBLEServer *server, NimBLEConnInfo &c, int reason) override {
    link().edit([&](LinkState &s) {
      s.connections = s.connections ? s.connections - 1 : 0;
      s.radio = advertiseAgain_ ? Radio::Advertising : Radio::Off;
      s.advertising = advertiseAgain_;
      s.lastDisconnect = reason;
      s.passkey = 0;
    });
    BLE_NOTE(Warn, "disconnected 0x%02X: %s", reason & 0xFF, disconnectReason(reason));
    (void)server;
  }

  void onMTUChange(uint16_t mtu, NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) { s.peer.mtu = mtu; });
    BLE_NOTE(Info, "MTU %u: %u bytes of data per packet", mtu, mtu - 3);
    (void)c;
  }

  void onConnParamsUpdate(NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) { fillPeer(s.peer, c); });
    BLE_NOTE(Info, "new params: %.2f ms, latency %u", c.getConnInterval() * 1.25f, c.getConnLatency());
  }

  void onPhyUpdate(NimBLEConnInfo &c, uint8_t tx, uint8_t rx) override {
    link().edit([&](LinkState &s) { s.peer.txPhy = tx, s.peer.rxPhy = rx; });
    BLE_NOTE(Info, "PHY now %s / %s", tx == 2 ? "2M" : tx == 3 ? "Coded" : "1M", rx == 2 ? "2M" : rx == 3 ? "Coded" : "1M");
    (void)c;
  }

  // ---- Pairing -------------------------------------------------------------------------------

  // Passkey entry, we display: six random digits, the other side types them.
  uint32_t onPassKeyDisplay() override {
    const uint32_t key = esp_random() % 1000000;
    link().edit([&](LinkState &s) { s.passkey = key ? key : 1, s.passkeyCompare = false, s.passkeySince = millis(); });
    BLE_NOTE(Warn, "passkey %06lu: type it on the other device", static_cast<unsigned long>(key));
    return key;
  }

  // Numeric comparison: both screens show the same 6 digits; a person says yes on both.
  void onConfirmPassKey(NimBLEConnInfo &c, uint32_t pin) override {
    pendingHandle_ = c.getConnHandle();
    link().edit([&](LinkState &s) { s.passkey = pin ? pin : 1, s.passkeyCompare = true, s.passkeySince = millis(); });
    BLE_NOTE(Warn, "compare %06lu: same on the phone? (click/yes)", static_cast<unsigned long>(pin));
  }

  void onAuthenticationComplete(NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) {
      fillPeer(s.peer, c);
      s.passkey = 0;
    });
    if (c.isEncrypted())
      BLE_NOTE(Good, "secured: %s%s, key %u B", c.isAuthenticated() ? "authenticated" : "Just Works", c.isBonded() ? ", bonded" : "", c.getSecKeySize());
    else
      BLE_NOTE(Bad, "pairing failed: still plain text");
  }

  void onIdentity(NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) { fillPeer(s.peer, c); });
    BLE_NOTE(Info, "identity: %s", c.getIdAddress().toString().c_str());
  }

  // Answer a numeric comparison (button or serial). False when nothing is waiting.
  bool confirm(bool yes) {
    if (pendingHandle_ == 0xFFFF) return false;
    NimBLEServer *server = NimBLEDevice::getServer();
    if (server) NimBLEDevice::injectConfirmPasskey(server->getPeerInfoByHandle(pendingHandle_), yes);
    pendingHandle_ = 0xFFFF;
    link().edit([&](LinkState &s) { s.passkey = 0; });
    BLE_NOTE(Info, "you said %s", yes ? "yes, it matches" : "no");
    return true;
  }
  bool comparing() const { return pendingHandle_ != 0xFFFF; }

  void setAdvertiseAgain(bool on) { advertiseAgain_ = on; }

 private:
  uint16_t pendingHandle_ = 0xFFFF;
  bool advertiseAgain_ = true;
};

}  // namespace ble

// Jumper wires as touch keys: the ESP32-S3's capacitive touch sensor.
//
// GPIO 1-14 can measure how much charge their pin holds. A finger on a bare wire end adds
// capacitance, so the reading rises (on the S3 it goes UP when touched; on the original ESP32
// it went down). We measure each pad with nobody touching it (the baseline) when you switch
// touch on, then call it touched above +25 % and released below +15 %: the gap (hysteresis)
// stops a finger hovering at the edge from flickering on and off.
//
// Shared by B5-B7 (kit/lib/ble-kit). Nothing to wire beyond a jumper in the pin, the other end loose. Keep your hands off the wires
// while `touch on` measures the baselines.
#pragma once

#include <Arduino.h>

template <int N>
class TouchPads {
 public:
  explicit TouchPads(const uint8_t (&pins)[N]) {
    for (int i = 0; i < N; i++) pins_[i] = pins[i];
  }

  bool on() const { return on_; }
  uint8_t pin(int i) const { return pins_[i]; }
  uint32_t value(int i) const { return value_[i]; }
  uint32_t baseline(int i) const { return base_[i]; }
  bool down(int i) const { return (down_ >> i) & 1; }
  // How far above the baseline, in percent (for a bar on screen and a velocity).
  int rise(int i) const { return base_[i] ? int((int64_t(value_[i]) - base_[i]) * 100 / base_[i]) : 0; }

  // Switch on: measure every pad 8 times with nobody touching. Takes ~0.1 s.
  void enable(bool on) {
    on_ = on;
    down_ = 0;
    if (!on) return;
    for (int i = 0; i < N; i++) {
      uint64_t sum = 0;
      for (int k = 0; k < 8; k++) sum += touchRead(pins_[i]);
      base_[i] = uint32_t(sum / 8);
      value_[i] = base_[i];
    }
  }

  // Every ~40 ms from loop(). Returns the pads that went down (bit i) since the last call;
  // `released` gets the ones that came up.
  uint32_t poll(uint32_t &released) {
    released = 0;
    if (!on_ || millis() - at_ < 40) return 0;
    at_ = millis();
    uint32_t pressed = 0;
    for (int i = 0; i < N; i++) {
      value_[i] = touchRead(pins_[i]);
      const bool was = down(i);
      const uint64_t v = uint64_t(value_[i]) * 100;
      if (!was && v > uint64_t(base_[i]) * 125) down_ |= 1u << i, pressed |= 1u << i;
      else if (was && v < uint64_t(base_[i]) * 115) down_ &= ~(1u << i), released |= 1u << i;
    }
    return pressed;
  }

 private:
  uint8_t pins_[N];
  uint32_t base_[N] = {}, value_[N] = {};
  uint32_t down_ = 0, at_ = 0;
  bool on_ = false;
};

// Drawing pieces every BLE lab shares (320 x 170, landscape):
//   header   "BLE" + the view's name, view dots, and the status cluster: what the radio is doing,
//            a lock when the link is encrypted, a key when the peer is bonded, signal bars
//   footer   the button hint on the left, the latest activity line on the right
//   link     a live connection: who is central, the connection events ticking, MTU, PHY, security
//   log      the activity log, newest at the bottom
//   passkey  the big 6 digits, drawn over any view while pairing waits for you
#pragma once

#include <Fonts/FreeSans9pt7b.h>
#include <Fonts/FreeSansBold24pt7b.h>
#include <Fonts/FreeSansBold9pt7b.h>
#include <math.h>

#include "ble_link.h"
#include "color.h"
#include "frame_buffer.h"

namespace bv {

constexpr int kW = 320, kH = 170, kTop = 30, kBottom = kH - 12;
// Bluetooth's own colours on the bench palette: blue = radio, violet = encrypted.
constexpr uint16_t kBlue = rgb(80, 150, 255);
constexpr uint16_t kViolet = rgb(176, 130, 255);
constexpr uint16_t kPanel = rgb(20, 28, 40);

inline int textWidth(FrameBuffer &fb, const char *s) {
  int16_t x1, y1;
  uint16_t w, h;
  fb.getTextBounds(s, 0, 0, &x1, &y1, &w, &h);
  return w;
}

inline void small(FrameBuffer &fb, int x, int y, uint16_t c, const char *s) {
  fb.setFont(nullptr);
  fb.setTextColor(c);
  fb.setCursor(x, y);
  fb.print(s);
}

inline void bold(FrameBuffer &fb, int x, int y, uint16_t c, const char *s) {
  fb.setFont(&FreeSansBold9pt7b);
  fb.setTextColor(c);
  fb.setCursor(x, y);
  fb.print(s);
}

// A label over a value, in a column.
inline void stat(FrameBuffer &fb, int x, int y, const char *label, const char *value, uint16_t c = pal::ink) {
  small(fb, x, y, pal::muted, label);
  bold(fb, x, y + 22, c, value);
}

// Four bars, like a phone's: -50 dBm and up = 4 bars, -90 and below = 0.
inline void signalBars(FrameBuffer &fb, int x, int y, int rssi, uint16_t on = pal::ink) {
  const int bars = rssi == 0 ? 0 : rssi >= -55 ? 4 : rssi >= -67 ? 3 : rssi >= -78 ? 2 : rssi >= -90 ? 1 : 0;
  for (int i = 0; i < 4; i++) {
    const int h = 3 + i * 3;
    fb.fillRect(x + i * 4, y + 12 - h, 3, h, i < bars ? on : pal::dim);
  }
}

inline uint16_t rssiColour(int rssi) { return rssi >= -67 ? pal::teal : rssi >= -82 ? pal::amber : pal::coral; }

inline void lockIcon(FrameBuffer &fb, int x, int y, uint16_t c) {
  fb.drawRoundRect(x + 2, y, 7, 7, 3, c);
  fb.fillRect(x, y + 5, 11, 8, c);
}

inline void keyIcon(FrameBuffer &fb, int x, int y, uint16_t c) {
  fb.drawCircle(x + 3, y + 6, 3, c);
  fb.drawFastHLine(x + 6, y + 6, 7, c);
  fb.drawFastVLine(x + 11, y + 6, 4, c);
  fb.drawFastVLine(x + 9, y + 6, 3, c);
}

// The radio's state as a small animated glyph centred on (x, y).
inline void radioGlyph(FrameBuffer &fb, int x, int y, ble::Radio r, float t) {
  switch (r) {
    case ble::Radio::Off: fb.drawCircle(x, y, 5, pal::dim); break;
    case ble::Radio::Scanning: {
      // A radar sweep: we are listening.
      fb.drawCircle(x, y, 7, pal::dim);
      const float a = t * 5.0f;
      fb.drawLine(x, y, x + int(cosf(a) * 7), y + int(sinf(a) * 7), pal::teal);
      fb.fillCircle(x, y, 1, pal::teal);
      break;
    }
    case ble::Radio::Advertising: {
      // Rings leaving the antenna: we are shouting.
      fb.fillCircle(x, y, 2, kBlue);
      for (int i = 0; i < 2; i++) {
        const float k = fmodf(t * 1.2f + i * 0.5f, 1.0f);
        fb.drawCircle(x, y, 3 + int(k * 6), mix(kBlue, pal::night, uint8_t(k * 255)));
      }
      break;
    }
    case ble::Radio::Connecting:
      fb.drawCircle(x, y, 6, (int(t * 6) & 1) ? pal::amber : pal::dim);
      break;
    case ble::Radio::Connected:
      // Two linked rings: a connection.
      fb.drawCircle(x - 3, y, 4, kBlue);
      fb.drawCircle(x + 3, y, 4, kBlue);
      break;
  }
}

inline void header(FrameBuffer &fb, const char *labId, const char *view, int index, int count, const ble::LinkState &s, float t) {
  fb.setFont(&FreeSansBold9pt7b);
  fb.setTextColor(kBlue);
  fb.setCursor(8, 18);
  fb.print(labId);
  fb.print(" ");
  fb.setFont(&FreeSans9pt7b);
  fb.setTextColor(pal::muted);
  fb.print(view);
  // Status cluster, right to left: signal, key, lock, radio.
  int x = 302;
  if (s.radio == ble::Radio::Connected && s.peer.rssi != 0) signalBars(fb, x, 9, s.peer.rssi, rssiColour(s.peer.rssi));
  x -= 18;
  if (s.peer.bonded && s.radio == ble::Radio::Connected) keyIcon(fb, x, 8, pal::amber), x -= 18;
  if (s.peer.encrypted && s.radio == ble::Radio::Connected) lockIcon(fb, x + 2, 7, kViolet), x -= 16;
  radioGlyph(fb, x + 4, 15, s.radio, t);
  const int firstDot = x - 14 - (count - 1) * 9;
  for (int i = 0; i < count; i++) fb.fillCircle(firstDot + i * 9, 15, 3, i == index ? pal::ink : pal::dim);
  fb.drawFastHLine(0, 28, kW, pal::dim);
}

inline uint16_t actColour(ble::Act k) {
  switch (k) {
    case ble::Act::Good: return pal::teal;
    case ble::Act::Warn: return pal::amber;
    case ble::Act::Bad: return pal::coral;
    case ble::Act::Rx: return kBlue;
    case ble::Act::Tx: return kViolet;
    default: return pal::muted;
  }
}

inline const char *actMark(ble::Act k) {
  switch (k) {
    case ble::Act::Good: return "+";
    case ble::Act::Warn: return "!";
    case ble::Act::Bad: return "x";
    case ble::Act::Rx: return "<";
    case ble::Act::Tx: return ">";
    default: return "-";
  }
}

// Left: the button hint. Right: the newest activity line, fading after 6 s.
inline void footer(FrameBuffer &fb, const char *hint) {
  fb.fillRect(0, kH - 11, kW, 11, pal::night);
  small(fb, 6, kH - 9, pal::muted, hint);
  ble::Activity &a = ble::activity();
  ble::ActEntry e;
  const uint32_t head = a.head();
  if (head == 0 || !a.get(head - 1, e)) return;
  const uint32_t age = millis() - e.ms;
  if (age > 6000) return;
  char right[30];
  strlcpy(right, e.text, sizeof(right));
  fb.setFont(nullptr);
  const uint16_t c = mix(actColour(e.kind), pal::night, uint8_t(age > 4000 ? (age - 4000) * 200 / 2000 : 0));
  small(fb, kW - 6 - textWidth(fb, right), kH - 9, c, right);
}

// ---- log ----------------------------------------------------------------------------------------

inline void log(FrameBuffer &fb, int y0 = kTop + 4, int rows = 10) {
  ble::Activity &a = ble::activity();
  const uint32_t head = a.head();
  if (head == 0) {
    small(fb, 8, y0 + 4, pal::muted, "Nothing on the air yet.");
    return;
  }
  const uint32_t from = head > uint32_t(rows) ? head - rows : 0;
  ble::ActEntry e;
  int y = y0;
  for (uint32_t i = from; i < head; i++, y += 12) {
    if (!a.get(i, e)) continue;
    char when[12];
    snprintf(when, sizeof(when), "%5lu.%lu", static_cast<unsigned long>(e.ms / 1000), static_cast<unsigned long>(e.ms / 100 % 10));
    small(fb, 4, y, pal::dim, when);
    small(fb, 50, y, actColour(e.kind), actMark(e.kind));
    char text[44];
    strlcpy(text, e.text, sizeof(text));
    small(fb, 60, y, i + 1 == head ? pal::ink : pal::muted, text);
  }
}

// ---- link ---------------------------------------------------------------------------------------

// The connection drawn as two devices and the connection events between them: one exchange every
// interval, the dot's speed is real time slowed down 20x so 7.5-50 ms intervals stay visible.
inline void link(FrameBuffer &fb, const ble::LinkState &s, float t, const char *usLabel = "this board", const char *themLabel = nullptr) {
  const bool up = s.radio == ble::Radio::Connected;
  const int ly = 62, lx = 30, rx = 150;
  fb.fillRoundRect(lx - 22, ly - 22, 44, 44, 6, kPanel);
  fb.drawRoundRect(lx - 22, ly - 22, 44, 44, 6, kBlue);
  fb.fillRoundRect(rx - 16, ly - 26, 32, 52, 6, kPanel);
  fb.drawRoundRect(rx - 16, ly - 26, 32, 52, 6, up ? kBlue : pal::dim);
  small(fb, lx - 18, ly + 28, pal::muted, usLabel);
  small(fb, rx - 18, ly + 28, pal::muted, themLabel ? themLabel : (up && s.peer.name[0] ? s.peer.name : "peer"));
  // Who leads: the central sets the timing, the peripheral answers in each event.
  small(fb, lx - 18, ly - 4, pal::ink, s.peer.central || !up ? "periph" : "central");
  small(fb, rx - 14, ly - 4, up ? pal::ink : pal::dim, s.peer.central ? "central" : "periph");
  if (up) {
    const float intervalMs = s.peer.interval * 1.25f;
    const float period = fmaxf(intervalMs * 20.0f / 1000.0f, 0.15f);
    const float k = fmodf(t, period) / period;
    const int x = lx + 24 + int(k * (rx - lx - 42));
    fb.drawFastHLine(lx + 24, ly - 6, rx - lx - 42, pal::dim);
    fb.drawFastHLine(lx + 24, ly + 6, rx - lx - 42, pal::dim);
    fb.fillCircle(x, ly - 6, 3, s.peer.encrypted ? kViolet : kBlue);
    fb.fillCircle(lx + 24 + (rx - lx - 42) - (x - lx - 24), ly + 6, 3, pal::teal);
    if (s.peer.encrypted) lockIcon(fb, (lx + rx) / 2 - 5, ly - 26, kViolet);
  } else {
    small(fb, lx + 30, ly - 3, pal::muted, s.advertising ? "waiting..." : "no link");
  }

  char v[40];
  const int cx = 190;
  if (!up) {
    stat(fb, cx, 38, "last link ended", s.lastDisconnect < 0 ? "-" : "", pal::muted);
    if (s.lastDisconnect >= 0) {
      snprintf(v, sizeof(v), "reason 0x%02X", s.lastDisconnect & 0xFF);
      bold(fb, cx, 60, pal::ink, v);
      char why[34];
      strlcpy(why, ble::disconnectReason(s.lastDisconnect), sizeof(why));
      small(fb, cx, 68, pal::muted, why);
    }
    return;
  }
  snprintf(v, sizeof(v), "%.2f ms", s.peer.interval * 1.25f);
  stat(fb, cx, 34, "interval", v, kBlue);
  snprintf(v, sizeof(v), "%u B", s.peer.mtu);
  stat(fb, cx + 74, 34, "MTU", v);
  snprintf(v, sizeof(v), "%u", s.peer.latency);
  stat(fb, cx, 70, "latency", v);
  snprintf(v, sizeof(v), "%u ms", s.peer.timeout * 10);
  stat(fb, cx + 74, 70, "timeout", v);
  static const char *const phy[] = {"?", "1M", "2M", "Coded"};
  snprintf(v, sizeof(v), "%s/%s", phy[s.peer.txPhy & 3], phy[s.peer.rxPhy & 3]);
  stat(fb, cx, 106, "PHY tx/rx", v);
  snprintf(v, sizeof(v), "%d dBm", s.peer.rssi);
  stat(fb, cx + 74, 106, "RSSI", s.peer.rssi ? v : "-", s.peer.rssi ? rssiColour(s.peer.rssi) : pal::muted);
  // Security row under the drawing.
  const uint16_t sc = s.peer.encrypted ? kViolet : pal::muted;
  snprintf(v, sizeof(v), "%s%s%s", s.peer.encrypted ? "encrypted" : "plain text", s.peer.authenticated ? " + MITM" : "", s.peer.bonded ? " + bonded" : "");
  small(fb, 8, 114, sc, v);
  snprintf(v, sizeof(v), "%s  up %lus", s.peer.addr, static_cast<unsigned long>((millis() - s.connectedAt) / 1000));
  small(fb, 8, 126, pal::muted, v);
  snprintf(v, sizeof(v), "rx %lu ops %lu B", static_cast<unsigned long>(s.rxOps), static_cast<unsigned long>(s.rxBytes));
  small(fb, 8, 138, kBlue, v);
  snprintf(v, sizeof(v), "tx %lu ops %lu B", static_cast<unsigned long>(s.txOps), static_cast<unsigned long>(s.txBytes));
  small(fb, 8, 148, kViolet, v);
}

